SOCKET_PATH = os.environ.get("SILC_SOCKET", "__SOCKET_PATH__")
IPC_DIR = os.environ.get("SILC_IPC_DIR", "ipc")
MODEL_PATH = os.environ["SILC_MODEL_PATH"]
MODEL_ID = os.environ.get("SILC_MODEL_ID", "llama3.2-1b")
ABI_VERSION = 1
PROTOCOL_VERSION = 1
SCHEMA_ID = __SCHEMA_ID__
HEADER_SIZE = 128
MAX_TOKENS = 256

print(f"silc: loading LLM {MODEL_ID} from {MODEL_PATH}", flush=True)
LLM = Llama(
    model_path=MODEL_PATH,
    n_ctx=2048,
    n_threads=max(1, (os.cpu_count() or 2) // 2),
    n_gpu_layers=-1,
    verbose=False,
)
